{"file_path":"src/policies.js","content":"/**
 * The two limiter policies. Each keeps one independent state per key, and each
 * answers the same three questions: advance to a tick, allow a request, record
 * a request.
 */

/**
 * A token bucket. Tokens are held as an exact fraction: the stored numerator
 * counts `per`ths of a token, so the `refill / per` tokens a tick is worth are
 * never rounded away.
 */
export class Bucket {
  constructor(name, capacity, refill, per) {
    this.name = name
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.full = capacity * per
    this.states = new Map()
  }

  state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokens: this.full, tick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.state(key)
    if (state.tick === null) {
      state.tick = tick
      return
    }
    const elapsed = tick - state.tick
    state.tick = tick
    if (elapsed <= 0n) return
    state.tokens += this.refill * elapsed
    if (state.tokens > this.full) state.tokens = this.full
  }

  allows(key) {
    return this.state(key).tokens >= this.per
  }

  record(key) {
    const state = this.state(key)
    state.tokens -= this.per
  }
}

/**
 * A sliding window. It remembers the ticks of the requests it recorded and
 * forgets those that have fallen out of the `span` ticks ending at the tick it
 * was last advanced to.
 */
export class Window {
  constructor(name, limit, span) {
    this.name = name
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  state(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [], head: 0 }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.state(key)
    const cutoff = tick - this.span
    while (state.head < state.ticks.length && state.ticks[state.head] <= cutoff) state.head += 1
    if (state.head > 0 && state.head === state.ticks.length) {
      state.ticks = []
      state.head = 0
    }
  }

  allows(key) {
    const state = this.state(key)
    return BigInt(state.ticks.length - state.head) < this.limit
  }

  record(key, tick) {
    this.state(key).ticks.push(tick)
  }
}
"}

