{"file_path":"src/parse.js","content":"/**
 * The limiter file parser. It turns the text of a file into the policies, the
 * routes and the event log, and it reports the first failure it meets as a
 * `LineError` carrying the line number and the reason.
 */

import { Bucket, Window } from './policies.js'

export class LineError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const TOKEN = /^[A-Za-z0-9_./:-]+$/
const INTEGER = /^(0|[1-9][0-9]*)$/

function isToken(word) {
  return TOKEN.test(word)
}

/** Reads an unsigned decimal count, refusing signs, leading zeroes and slack. */
function count(word, field, least, line) {
  if (!INTEGER.test(word)) throw new LineError(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(word)
  if (value < least) throw new LineError(line, `${field} must be an integer of at least ${least}`)
  return value
}

/** Splits the file into lines, dropping the empty tail a trailing newline leaves. */
export function splitLines(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

export function parse(text) {
  const policies = new Map()
  const routes = new Map()
  const events = []
  let started = false
  let last = null

  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const number = index + 1
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'bucket' || directive === 'window' || directive === 'route') {
      if (started) throw new LineError(number, 'declarations must come before the first event')
    }

    if (directive === 'bucket') {
      if (words.length !== 5) throw new LineError(number, 'expected bucket <name> <capacity> <refill> <per>')
      const name = words[1]
      if (!isToken(name)) throw new LineError(number, `invalid policy name ${name}`)
      const capacity = count(words[2], 'capacity', 1n, number)
      const refill = count(words[3], 'refill', 0n, number)
      const per = count(words[4], 'per', 1n, number)
      if (policies.has(name)) throw new LineError(number, `policy ${name} is declared twice`)
      policies.set(name, new Bucket(name, capacity, refill, per))
    } else if (directive === 'window') {
      if (words.length !== 4) throw new LineError(number, 'expected window <name> <limit> <span>')
      const name = words[1]
      if (!isToken(name)) throw new LineError(number, `invalid policy name ${name}`)
      const limit = count(words[2], 'limit', 0n, number)
      const span = count(words[3], 'span', 1n, number)
      if (policies.has(name)) throw new LineError(number, `policy ${name} is declared twice`)
      policies.set(name, new Window(name, limit, span))
    } else if (directive === 'route') {
      if (words.length < 3) throw new LineError(number, 'expected route <prefix> <policy>...')
      const prefix = words[1]
      if (!isToken(prefix)) throw new LineError(number, `invalid route prefix ${prefix}`)
      const named = []
      for (const name of words.slice(2)) {
        const policy = policies.get(name)
        if (policy === undefined) throw new LineError(number, `unknown policy ${name}`)
        named.push(policy)
      }
      if (routes.has(prefix)) throw new LineError(number, `prefix ${prefix} is routed twice`)
      routes.set(prefix, named)
    } else if (directive === 'event') {
      if (words.length !== 3) throw new LineError(number, 'expected event <tick> <key>')
      const tick = count(words[1], 'tick', 0n, number)
      const key = words[2]
