{"file_path":"src/simulate.js","content":"/**
 * The simulation and its two reports. Every event is routed to the policies of
 * the longest prefix that matches its key; they all advance, they are all
 * asked, and only a unanimous yes is recorded.
 */

/** Finds the policies of the longest route prefix the key starts with. */
function routeFor(routes, key) {
  let best = null
  let length = -1
  for (const [prefix, policies] of routes) {
    if (key.startsWith(prefix) && prefix.length > length) {
      best = policies
      length = prefix.length
    }
  }
  return best === null ? [] : best
}

/** Verdicts every event in log order. */
export function simulate({ routes, events }) {
  const verdicts = []
  for (const { tick, key } of events) {
    const policies = routeFor(routes, key)
    for (const policy of policies) policy.advance(key, tick)
    let refused = null
    for (const policy of policies) {
      if (!policy.allows(key)) {
        refused = policy
        break
      }
    }
    if (refused === null) {
      for (const policy of policies) policy.record(key, tick)
      verdicts.push({ tick, key, allowed: true, by: null })
    } else {
      verdicts.push({ tick, key, allowed: false, by: refused.name })
    }
  }
  return verdicts
}

export function replay(verdicts) {
  let out = ''
  for (const verdict of verdicts) {
    out += verdict.allowed
      ? `${verdict.tick} ${verdict.key} allow\n`
      : `${verdict.tick} ${verdict.key} deny ${verdict.by}\n`
  }
  return out
}

export function summary(verdicts) {
  const counts = new Map()
  let allowed = 0
  let denied = 0
  for (const verdict of verdicts) {
    let tally = counts.get(verdict.key)
    if (tally === undefined) {
      tally = { allowed: 0, denied: 0 }
      counts.set(verdict.key, tally)
    }
    if (verdict.allowed) {
      tally.allowed += 1
      allowed += 1
    } else {
      tally.denied += 1
      denied += 1
    }
  }
  const keys = [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))
  let out = ''
  for (const key of keys) {
    const tally = counts.get(key)
    out += `${key} allowed=${tally.allowed} denied=${tally.denied}\n`
  }
  out += `total allowed=${allowed} denied=${denied}\n`
  return out
}
"}

