{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { parse, LineError } from './parse.js'
import { simulate, replay, summary } from './simulate.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'replay' && mode !== 'summary')) fail('usage: cli.js replay|summary')

  let verdicts
  try {
    verdicts = simulate(parse(readStdin()))
  } catch (error) {
    if (error instanceof LineError) fail(error.message)
    throw error
  }

  process.stdout.write(mode === 'replay' ? replay(verdicts) : summary(verdicts))
}

main(process.argv.slice(2))
"}

